import React from "react";
import { useNavigate } from "react-router-dom";
import axiosInstance from "../configurations/instance";

function AddChecker() {
  const [state, setState] = React.useState({
    name: "",
    surname: "",
    email: "",
    role: "Checker",
    password: "",
  });

  const navigate = useNavigate();

  const handleSubmit = () => {
    const { name, surname, email, role, password } = state;

    axiosInstance
      .post("/checker/create-checker", { name, surname, email, role, password })
      .then((response) => {
        console.log("Проверяющий создан:", response.data);

        // Сохраняем данные в localStorage
        localStorage.setItem("email", email);
        localStorage.setItem("token", response.data.token);

        // Перенаправляем на страницу верификации проверяющего
        navigate("/verify-checker");
      })
      .catch((error) => {
        console.error("Ошибка при создании проверяющего:", error);
      });
  };

  return (
    <div>
      <h1>Добавление Проверяющего</h1>
      <form>
        <label>Имя</label>
        <input
          value={state.name}
          onChange={(e) => setState({ ...state, name: e.target.value })}
        />

        <label>Фамилия</label>
        <input
          value={state.surname}
          onChange={(e) => setState({ ...state, surname: e.target.value })}
        />

        <label>Почта</label>
        <input
          value={state.email}
          onChange={(e) => setState({ ...state, email: e.target.value })}
        />

        <label>Пароль</label>
        <input
          type="password"
          value={state.password}
          onChange={(e) => setState({ ...state, password: e.target.value })}
        />

        <button type="button" onClick={handleSubmit}>
          Создать
        </button>
      </form>
    </div>
  );
}

export default AddChecker;
